      SUBROUTINE FORMCC     SET UP NORMALIZED EQUATIONS FOR FITTINGCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'BROAD.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM10F.CIN'      INCLUDE 'ELM39C.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'STEPT1.CIN'CC     LOCAL VARIABLESC      INTEGER         VARY      REAL            LIMIT      EXTERNAL        IDATACC---------------------------------------------------------------C     ZERO LOWER LEFT HALF OF MATRIX OF NORMAL EQUATIONSC      NP1 = NV3 + 1      DO 10 L1 = 1, NP1      DO 10 L2 = 1, L1      CA(L1,L2) = 0.0   10 CONTINUECC     FILL IN MATRIX OF NORMAL EQUATIONSC      IF (LSTEP .AND. BROAD) GO TO 20      IF (NSTEP .GE. 1 .AND. NCTV .LT. NCTE) THEN        NUM = NUMV        DOPARS = .TRUE.        NCTS = NCTV        NCTF = NCTE - 1        CALL MARCH        IF (FLUSHL) GO TO 200      ENDIF      DOPARS = .FALSE.      NCTS = NCTE      NCTF = NCTC      CALL MARCH      IF (FLUSHL) GO TO 200      GO TO 30CC     BROAD BAND CASEC   20 DO 25 NSTEPP = 1, NSTEPS      CALL STEPIT      IF (NSTEP .GE. 1 .AND. NCTV .LT. NCTE) THEN        NUM = NUMV        DOPARS = .TRUE.        NCTS = NCTV        NCTF = NCTE - 1        CALL MARCH        IF (FLUSHL) GO TO 200      ENDIF      DOPARS = .FALSE.      NCTS = NCTE      NCTF = NCTC      CALL MARCH      IF (FLUSHL) GO TO 200   25 CONTINUECC     SYMMETRIZE MATRIXC   30 DO 35 L1 = 2, NV1, 1      L1P1 = L1 + 1      DO 35 L2 = L1P1, NP1      CA(L1,L2) = CA(L2,L1)   35 CONTINUECC     DETERMINE WHICH VARIABLES WILL NOT HIT LIMITSC      DO 40 N = 1, NP1   40 ACTIV(N) = .TRUE.C      CALL INITLC      DO 100 NUM = 1, NEL      I = ISTOR(NUM)      TYPE = IDATA(I)      IF (TYPE .LE. 0 .OR. TYPE .GE. 50) GO TO 100      IF (TYPE .EQ. 23) GO TO 100      CALL SKETCH(NUM)      IF (TYPE .EQ. 39) GO TO 80      NVT = NV(TYPE)      IF (NVT .LT. 1) GO TO 100      DO 60 J = 1, NVT      IPT = IPTOJ(J)      IF (IPT .EQ. 0) GO TO 60      IPLUSJ = I + IPT      VARY = TIE(IPLUSJ)      IF (VARY .EQ. 0 .OR. VARY .GE. 99) GO TO 60      IVARY = IABS(VARY) + 1      SIG = SIGNF(FLOAT(VARY))      X2 = DATA(IPLUSJ)C      SI = LIMIT(TYPE,J,2)      IF (SI .EQ. 0.0) GO TO 50      SI = LIMIT(TYPE,J,1)      IF (X2 .GT. SI) GO TO 50      ACTIV(IVARY) = ACTIV(IVARY) .AND. SIG*CA(IVARY,1) .GE. 0.0C   50 SI = LIMIT(TYPE,J,4)      IF (SI .EQ. 0.0) GO TO 60      SI = LIMIT(TYPE,J,3)      IF (X2 .LT. SI) GO TO 60      ACTIV(IVARY) = ACTIV(IVARY) .AND. SIG*CA(IVARY,1) .LE. 0.0   60 CONTINUE      GO TO 100C   80 TYPEL = INT(DATA(I+1))      NPARL = INT(DATA(I+2))      IF (IPTOJ(3) .NE. 0) THEN        IPT = IPTOJ(3)        LTYPE = 1        DPARL = DATA(I+IPT)        CALL LIMSET      ENDIF      IF (IPTOJ(4) .NE. 0) THEN        IPT = IPTOJ(4)        LTYPE = 2        DPARL = DATA(I+IPT)        CALL LIMSET      ENDIF      IF (IPTOJ(5) .NE. 0) THEN        IPT = IPTOJ(5)        LTYPE = 1        DPARL = DATA(I+IPT)        DPARL = - ABS(DPARL)        CALL LIMSET        LTYPE = 2        DPARL = ABS(DPARL)        CALL LIMSET      ENDIFC  100 CONTINUEC      NACTIV = 0      DO 110 N = 2, NP1      IF (ACTIV(N)) NACTIV = NACTIV + 1  110 CONTINUEC      IF (CHSMIN .GT. 0.0 .AND. CA(1,1) .GE. CHSMIN) GO TO 200      CHSMIN = CA(1,1)      DO 120 N = 2, NP1      IF (.NOT. ACTIV(N)) THEN        DO 115 J = 1, NP1        CA(J,N) = 0.0  115   CA(N,J) = 0.0      ENDIF  120 CONTINUECC     SAVE CA ARRAYC      DO 140 J = 1, NP1      DO 140 K = 1, NP1  140 CASAV(J,K) = CA(J,K)CC     CALCULATE MAGNITUDE OF GRADIENTC      GNORM = 0.0      DO 150 J = 2, NP1      CAJ1 = CA(J,1)  150 GNORM = GNORM + CAJ1*CAJ1      GNORM = SQRT(GNORM)C  200 RETURN      END